-- Advanced forecasting lessons 20-24; idempotent seed, draft-only.
with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (
 insert into public.academy_chapters(course_id,title,description,sort_order,published)
 select id,'التنبؤ المتقدم والتحقق من المخرجات','التنبؤ التجميعي والفيزياء والهطول والتحقق الإحصائي وتصحيح مخرجات النماذج.',6,false
 from c on conflict(course_id,title) do update set description=excluded.description returning id,course_id
),
u1 as (
 insert into public.academy_units(chapter_id,title,description,sort_order,published)
 select id,'التنبؤ التجميعي وعدم اليقين','قراءة أعضاء المجموعة والانتشار والاحتمالات.',1,false from ch
 on conflict(chapter_id,title) do update set description=excluded.description returning id,chapter_id
),
u2 as (
 insert into public.academy_units(chapter_id,title,description,sort_order,published)
 select id,'فيزياء النماذج العددية','المعلمات الفيزيائية والسحب والحمل والطبقة الحدية والإشعاع.',2,false from ch
 on conflict(chapter_id,title) do update set description=excluded.description returning id,chapter_id
),
u3 as (
 insert into public.academy_units(chapter_id,title,description,sort_order,published)
 select id,'توقع الهطول والطقس الحاد','الرطوبة والاستقرار والرفع والقص وتقييم المخاطر.',3,false from ch
 on conflict(chapter_id,title) do update set description=excluded.description returning id,chapter_id
),
u4 as (
 insert into public.academy_units(chapter_id,title,description,sort_order,published)
 select id,'التحقق الإحصائي من التنبؤ','مقاييس التحقق والانحياز والمعايرة والمعالجة اللاحقة.',4,false from ch
 on conflict(chapter_id,title) do update set description=excluded.description returning id,chapter_id
),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values
('ensemble-weather-forecasting','النماذج التجميعية والتنبؤ الاحتمالي (Ensemble)','فهم أعضاء المجموعة وانتشار الحلول والاحتمالات ومهارات تفسير عدم اليقين.','{"blocks":[{"type":"heading","text":"لماذا نستخدم التنبؤ التجميعي؟"},{"type":"text","text":"الغلاف الجوي نظام حساس للشروط الابتدائية والتمثيلات الفيزيائية. لذلك لا يكفي تشغيل واحد لإظهار كل الاحتمالات المعقولة. تشغل أنظمة المجموعة عدة أعضاء مع تغييرات مضبوطة في البداية أو الفيزياء أو كليهما."},{"type":"heading","text":"أعضاء المجموعة"},{"type":"text","text":"كل عضو هو محاكاة مستقلة نسبياً ضمن تصميم المجموعة. لا تمثل الأعضاء بالضرورة احتمالات متساوية تماماً في كل نظام، لكنها توفر عينة من الحلول الممكنة ضمن منهج بناء المجموعة."},{"type":"heading","text":"الانتشار وعدم اليقين"},{"type":"list","items":["تقارب الأعضاء يشير غالباً إلى اتفاق أكبر ضمن المجموعة.","اتساع الانتشار يشير إلى عدم يقين أكبر أو حساسية أعلى في السيناريو.","الاتفاق لا يضمن الصحة؛ فقد تشترك الأعضاء في انحياز أو خطأ منهجي.","تتغير مهارة المجموعة حسب المتغير والمنطقة ومهلة التنبؤ ونوع الحالة."]},{"type":"heading","text":"المتوسط والوسيط والمدى"},{"type":"text","text":"يمكن تلخيص أعضاء المجموعة بالمتوسط أو الوسيط أو المئينات والمدى. يخفي المتوسط أحياناً تعدد السيناريوهات، لذلك افحص التوزيع الكامل ومراكز التجمع ولا تعتمد على قيمة واحدة."},{"type":"heading","text":"الاحتمالات"},{"type":"text","text":"يمكن تقدير احتمال تجاوز عتبة معينة بعدد الأعضاء التي تتجاوزها مقسوماً على عدد الأعضاء، مع مراعاة حجم المجموعة ومعايرتها ومهارتها التاريخية. هذه النسبة ليست احتمالاً مثالياً تلقائياً، بل تقدير يحتاج إلى تحقق ومعايرة."},{"type":"heading","text":"السيناريوهات المتعددة"},{"type":"list","items":["حدد المتغير والعتبة والفترة والمنطقة بوضوح.","افحص احتمال تحقق كل سيناريو وشدة أثره.","قارن التغير بين التشغيلات والمجموعات المختلفة.","استخدم الاحتمال مع أثر الحالة لتحديد الأولوية التشغيلية."]},{"type":"callout","text":"لا تفسر 70% من أعضاء المجموعة على أنها ضمان لحدوث الظاهرة. جودة الاحتمال تعتمد على معايرة المجموعة ومهارتها التاريخية وحجم العينة."},{"type":"example","text":"مثال: تجاوزت 14 عضواً من أصل 20 عتبة هطول محددة خلال 24 ساعة. النسبة الخام 70% داخل هذه المجموعة، لكن ينبغي فحص المعايرة السابقة والتوزيع المكاني وشدة الهطول قبل إصدار الاحتمال التشغيلي."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"تساعد النماذج التجميعية على وصف نطاق الحلول وعدم اليقين. أفضل استخدام لها يجمع الاحتمال والانتشار والمهارة السابقة والأثر المتوقع."}]}',200,40,'["شرح مفهوم التنبؤ التجميعي وأسباب تعدد الأعضاء","تفسير الانتشار والاحتمالات والسيناريوهات","استخدام منتجات المجموعة لدعم القرار التنبؤي"]','التنبؤ التجميعي وعدم اليقين'),
('physical-parameterizations-in-nwp','المعلمات الفيزيائية في النماذج العددية','تعرف إلى تمثيل السحب والحمل والإشعاع والطبقة الحدية والتدفقات السطحية.','{"blocks":[{"type":"heading","text":"ما المعلمات الفيزيائية؟"},{"type":"text","text":"المعلمات الفيزيائية (Parameterizations) هي طرق تقريبية لتمثيل عمليات أصغر من مقياس الشبكة أو غير محلولة مباشرة في النموذج. تحول أثر هذه العمليات إلى تدفقات أو معدلات تغير للمتغيرات المحسوبة."},{"type":"heading","text":"السحب والعمليات الدقيقة"},{"type":"text","text":"تمثل مخططات السحب الدقيقة تكوّن قطرات الماء والبلورات الجليدية والتجمد والانصهار والترسيب والتصادم. تختلف المخططات في عدد الفئات والعمليات المفترضة، ما يؤثر في توقيت الهطول ونوعه وتوزيعه."},{"type":"heading","text":"الحمل الحراري"},{"type":"text","text":"في الشبكات التي لا تحل الخلايا الحملية صراحة، قد يستخدم النموذج مخططاً للحمل العميق والضحل. وعند دقة أعلى قد تصبح بعض الخلايا الحملية ممثلة جزئياً أو مباشرة، لكن ذلك لا يلغي الحاجة إلى فهم إعدادات النموذج."},{"type":"heading","text":"الطبقة الحدية والتدفقات السطحية"},{"type":"text","text":"تمثل مخططات الطبقة الحدية الخلط الاضطرابي قرب السطح، بينما تنظم مخططات السطح تبادل الحرارة والرطوبة والزخم بين الأرض أو البحر والغلاف الجوي. تؤثر هذه العمليات في الضباب والرياح اليومية ودرجات الحرارة."},{"type":"heading","text":"الإشعاع والغطاء السحابي"},{"type":"text","text":"تحسب مخططات الإشعاع انتقال الطاقة الشمسية والأرضية وامتصاصها وانعكاسها. تؤثر السحب والهباء الجوي والغازات في ميزانية الطاقة والتسخين والتبريد."},{"type":"heading","text":"لماذا تختلف النماذج؟"},{"type":"list","items":["تختلف المخططات الفيزيائية ومعاملاتها وافتراضاتها.","تختلف الشبكات والمستويات وبيانات السطح.","تختلف طرق استيعاب البيانات والشروط الابتدائية.","قد تختلف طريقة تفاعل المخططات بعضها مع بعض."]},{"type":"callout","text":"زيادة الدقة الأفقية لا تعني إلغاء جميع المعلمات الفيزيائية. يجب معرفة إعدادات النموذج قبل تفسير الفروق بين خرائطه."},{"type":"example","text":"مثال: يعطي نموذجان توقيتاً مختلفاً لبداية الهطول الحملي. قارن دقة الشبكة ومخطط الحمل والسحب الدقيقة والرطوبة وملف الاستقرار، ولا تنسب الفرق إلى عامل واحد دون دليل."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"الفيزياء الممثلة داخل النموذج تؤثر مباشرة في السحب والهطول والحرارة والرياح. فهمها ضروري لتفسير اختلاف المخرجات وحدودها."}]}',210,40,'["شرح مفهوم المعلمات الفيزيائية ولماذا نحتاجها","تمييز أهم مخططات الفيزياء الجوية","تقييم أثر اختلاف الفيزياء في مخرجات النموذج"]','فيزياء النماذج العددية'),
('precipitation-and-thunderstorm-forecasting','التنبؤ بالهطول والعواصف الرعدية','دمج الرطوبة والرفع والاستقرار والقص والميكروفيزياء لتقدير فرص الهطول والعواصف.','{"blocks":[{"type":"heading","text":"من أين يبدأ التنبؤ؟"},{"type":"text","text":"يحتاج الهطول إلى مصدر رطوبة وآلية رفع وتبريد يسمح بالوصول إلى التشبع وعمليات سحابية تنتج قطرات أو بلورات تكبر حتى تصبح قابلة للسقوط. تختلف مساهمة كل عنصر حسب نوع الحالة."},{"type":"heading","text":"عناصر التنبؤ بالعواصف"},{"type":"list","items":["الرطوبة في الطبقات المنخفضة والمتوسطة وعمق الطبقة الرطبة.","عدم الاستقرار مثل CAPE مع تقييم CIN ومستوى بدء الحمل.","آلية الرفع مثل الجبهات والتقارب والتضاريس والموجات العلوية.","القص الرأسي للرياح وتنظيم الخلايا الحملية.","الغطاء السحابي والتسخين النهاري ودرجة حرارة السطح."]},{"type":"heading","text":"قراءة منتجات الهطول"},{"type":"text","text":"ميّز بين الهطول التراكمي خلال نافذة زمنية ومعدل الهطول في لحظة أو فترة قصيرة. افحص فترة التجميع، ووقت بدء التراكم، والوحدة، ومخرجات كل نموذج قبل المقارنة."},{"type":"heading","text":"التنبؤ المكاني والزمني"},{"type":"text","text":"قد تكون مواقع الخلايا الحملية حساسة للتضاريس والتقارب والتسخين المحلي، لذلك قد تكون الثقة في حدوث بيئة مواتية أعلى من الثقة في موقع خلية بعينها قبل وقت قصير. استخدم الرادار والأقمار الصناعية والرصد لتحديث التوقع."},{"type":"heading","text":"العواصف والقص"},{"type":"text","text":"يساعد القص الرأسي على تنظيم الحمل وتحديد نمط الخلايا، لكنه لا يكفي منفرداً لتحديد شدة العاصفة. يجب دمجه مع عدم الاستقرار والرطوبة والرفع والحدود الجوية."},{"type":"heading","text":"تقدير المخاطر"},{"type":"list","items":["احتمال حدوث الهطول أو العواصف.","الشدة المحتملة والمدة والتراكم.","المساحة المتأثرة والتوقيت المتوقع.","درجة الثقة ومصادر عدم اليقين.","مقارنة التوقع بالرادار والرصد والتنبيهات الرسمية."]},{"type":"callout","text":"لا تستنتج العواصف الرعدية من CAPE وحدها، ولا تستنتج الفيضانات من مجموع هطول نموذجي دون تقييم شدة المطر والتضاريس والتربة والتصريف والرصد."},{"type":"example","text":"مثال: تتوافر رطوبة وعدم استقرار مع تقارب سطحي واقتراب أخدود علوي. افحص CIN والقص والحركة الرأسية وتوقيت الرفع، ثم استخدم الرادار والأقمار الصناعية لتحديث موقع الخلايا المحتملة."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"التنبؤ بالهطول والعواصف عملية متعددة العناصر. يجب دمج بيئة الحمل مع الرفع والرطوبة والقص والمنتجات الرصدية وتحديد الثقة."}]}',220,45,'["تقييم عناصر تكوّن الهطول والحمل الرعدي","قراءة خرائط الهطول التراكمي ومعدلاته","دمج الاستقرار والرفع والقص والرصد في التوقع"]','توقع الهطول والطقس الحاد'),
('weather-forecast-verification','التحقق من دقة التنبؤات الجوية (Verification)','تعلم مقارنة التوقع بالرصد واختيار مقاييس مناسبة للمتغيرات والظواهر.','{"blocks":[{"type":"heading","text":"لماذا نتحقق؟"},{"type":"text","text":"التحقق يقيس مدى توافق التنبؤات مع ما رُصد فعلياً. يساعد على معرفة نقاط القوة والضعف ومقارنة النماذج ومتابعة تغير الأداء عبر المواسم والمناطق ومهل التنبؤ."},{"type":"heading","text":"أساس المقارنة العادلة"},{"type":"list","items":["طابق الوقت الصالح وموقع الرصد ومهلة التنبؤ.","استخدم وحدات وتعريفات متوافقة بين التوقع والرصد.","افحص جودة الرصد وتمثيله للمساحة التي تصفها شبكة النموذج.","حدد عينة مستقلة كافية وتجنب انتقاء الحالات الناجحة فقط.","افصل النتائج حسب الموسم والمنطقة ونوع الحالة ومهلة التنبؤ."]},{"type":"heading","text":"المقاييس للمتغيرات المستمرة"},{"type":"text","text":"يستخدم متوسط الخطأ (Bias) لقياس الانحراف المنتظم، ومتوسط الخطأ المطلق (MAE) لقياس مقدار الخطأ دون إشارة، والجذر التربيعي لمتوسط مربع الخطأ (RMSE) لإعطاء وزن أكبر للأخطاء الكبيرة. لكل مقياس تفسيره ولا يكفي منفرداً."},{"type":"formula","text":"Bias = mean(F − O)"},{"type":"formula","text":"MAE = mean(|F − O|)"},{"type":"formula","text":"RMSE = sqrt(mean((F − O)²))"},{"type":"heading","text":"الظواهر الثنائية"},{"type":"text","text":"عند تقييم حدوث ظاهرة أو عدم حدوثها يمكن استخدام جدول التوافق الذي يصنف الحالات إلى إصابة صحيحة وإنذار كاذب وفشل ورفض صحيح. ومنه تحسب مقاييس مثل Probability of Detection وFalse Alarm Ratio وCritical Success Index."},{"type":"heading","text":"التنبؤات الاحتمالية"},{"type":"text","text":"تحتاج الاحتمالات إلى تقييم الموثوقية والتمييز والمهارة. يقارن مخطط الموثوقية الاحتمال المتوقع بتكرار الحدث المرصود ضمن مجموعات احتمالية، ويمكن استخدام Brier Score للنتائج الثنائية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["مقارنة مواقع شبكية بمحطات دون مراعاة التمثيل المكاني.","تجميع جميع المواسم والمناطق في رقم واحد يخفي الاختلافات.","تغيير عتبة الحدث أو نافذة الزمن بين النموذج والرصد.","الاعتماد على مقياس واحد أو عينة صغيرة."]},{"type":"callout","text":"لا يعني انخفاض RMSE في متغير واحد أن النموذج أفضل في جميع المتغيرات أو الظواهر. اختر المقاييس بحسب غرض التنبؤ وطبيعة البيانات."},{"type":"example","text":"مثال: عند تقييم توقع المطر، طابق نافذة التجميع مع المطر المرصود، ثم احسب جدول التوافق عند عتبة محددة، واذكر حجم العينة والمنطقة والفترة قبل مقارنة نموذجين."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"التحقق عملية منهجية تحتاج إلى مطابقة عادلة للبيانات واختيار مقياس مناسب وتقسيم النتائج حسب السياق."}]}',230,40,'["شرح ضرورة التحقق المستقل من التوقعات","اختيار مقاييس أساسية للمتغيرات المستمرة والثنائية","تمييز الانحياز والدقة والمهارة والموثوقية"]','التحقق الإحصائي من التنبؤ'),
('model-bias-and-statistical-postprocessing','الانحياز الإحصائي وتصحيح مخرجات النماذج','تعرف إلى الانحياز المنهجي والمعايرة والمعالجة اللاحقة وحدود التصحيح الإحصائي.','{"blocks":[{"type":"heading","text":"ما الانحياز؟"},{"type":"text","text":"الانحياز هو ميل منتظم إلى المبالغة أو التقليل في توقع متغير ما ضمن عينة أو سياق محدد. قد يظهر في الحرارة أو الرياح أو الهطول، وقد يتغير حسب الموسم والمنطقة ومهلة التنبؤ."},{"type":"heading","text":"مصادر الانحياز"},{"type":"list","items":["تمثيل غير دقيق للتضاريس أو السطح.","اختلافات فيزيائية أو أخطاء منهجية في النموذج.","نقص أو انحياز في الرصد المستخدم للتحقق.","تأثيرات محلية غير ممثلة جيداً في الشبكة.","تغيرات في إصدار النموذج أو نظام الاستيعاب."]},{"type":"heading","text":"الفرق بين الانحياز والخطأ"},{"type":"text","text":"يمكن أن يكون متوسط الانحياز قريباً من الصفر مع وجود أخطاء كبيرة موجبة وسالبة تلغي بعضها بعضاً. لذلك يجب عرض الانحياز مع مقاييس أخرى مثل MAE وRMSE وتوزيع الأخطاء."},{"type":"heading","text":"المعالجة الإحصائية اللاحقة"},{"type":"text","text":"تستخدم المعالجة اللاحقة (Post-processing) العلاقة التاريخية بين مخرجات النموذج والرصد لتحسين التوقعات. قد تشمل تصحيحاً خطياً أو معايرة احتمالية أو طرائق أكثر تعقيداً، ويجب اختيارها وفق نوع المتغير وتوفر بيانات موثوقة."},{"type":"heading","text":"مبادئ التصحيح المسؤول"},{"type":"list","items":["اجمع عينة تاريخية ممثلة تشمل الفصول والأنظمة المختلفة.","افصل بيانات التدريب عن بيانات التحقق المستقلة زمنياً.","اختبر الأداء بحسب الموقع والموسم ومهلة التنبؤ.","راقب تغير أداء النموذج بعد تحديثه ولا تفترض ثبات الانحياز.","احتفظ بالمخرجات الخام إلى جانب المصححة لتتبع الأثر."]},{"type":"heading","text":"خطر الإفراط في الملاءمة"},{"type":"text","text":"قد يتعلم التصحيح تفاصيل عشوائية في عينة التدريب ولا يعمم على حالات جديدة. استخدم تحققاً مستقلاً أو تحققاً متقاطعاً زمنياً، وراقب حجم العينة وعدم الاستقرار."},{"type":"heading","text":"حدود التصحيح"},{"type":"text","text":"لا يستطيع التصحيح الإحصائي استعادة كل التفاصيل الفيزيائية المفقودة أو ضمان تصحيح الحالات النادرة. وقد يؤدي تطبيق علاقة ثابتة على نظام جوي مختلف أو إصدار نموذج جديد إلى نتائج مضللة."},{"type":"callout","text":"لا تحذف التوقع الخام ولا تصف التوقع المصحح بأنه حقيقة. وثّق طريقة التصحيح ومجال صلاحيتها وتاريخ تدريبها ومقاييس أدائها."},{"type":"example","text":"مثال: تظهر سجلات عدة مواسم أن النموذج يميل إلى رفع درجة الحرارة الليلية في موقع معين. ابنِ تصحيحاً باستخدام فترة تدريب، ثم اختبره على فترة زمنية منفصلة وقارن Bias وMAE قبل التصحيح وبعده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"التصحيح الإحصائي يحسن بعض الأخطاء المنهجية عندما تكون مستقرة ومدعومة ببيانات كافية. التحقق المستقل ومراقبة تغير النموذج شرطان أساسيان."}]}',240,40,'["تعريف الانحياز وأسبابه ومتى يكون مستقراً","تمييز المعالجة اللاحقة عن التحقق","شرح مبادئ المعايرة والتصحيح مع تجنب الإفراط في الملاءمة"]','التحقق الإحصائي من التنبؤ')
)
insert into public.academy_lessons
(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,
case d.unit when 'التنبؤ التجميعي وعدم اليقين' then u1.id when 'فيزياء النماذج العددية' then u2.id when 'توقع الهطول والطقس الحاد' then u3.id else u4.id end,
d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,
'التنبؤ المتقدم والتحقق من المخرجات',d.unit
from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4
on conflict(course_id,slug) do update set
chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,
content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,
estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,
chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;